ALTER TABLE "anchor_evidence" DROP CONSTRAINT "anchor_evidence_location_check";--> statement-breakpoint
ALTER TABLE "anchor_evidence" ADD CONSTRAINT "anchor_evidence_location_check" CHECK (("anchor_evidence"."kind" = 'link' AND "anchor_evidence"."url" ~ '^https://' AND "anchor_evidence"."storage_reference" IS NULL AND "anchor_evidence"."scan_status" = 'not_required' AND "anchor_evidence"."content_type" IS NULL AND "anchor_evidence"."byte_size" IS NULL AND "anchor_evidence"."sha256" IS NULL AND "anchor_evidence"."scan_result" IS NULL AND "anchor_evidence"."scanned_at" IS NULL) OR ("anchor_evidence"."kind" = 'upload' AND "anchor_evidence"."url" IS NULL AND length("anchor_evidence"."storage_reference") BETWEEN 1 AND 512 AND "anchor_evidence"."storage_reference" ~ '^[a-zA-Z0-9][a-zA-Z0-9._:/-]*$' AND "anchor_evidence"."scan_status" = 'clean' AND "anchor_evidence"."scan_result" IS NOT NULL AND "anchor_evidence"."scanned_at" IS NOT NULL));